<?php
$dir = __DIR__."/admin";
if(!is_dir($dir)) mkdir($dir,0755,true);
$ok = file_put_contents($dir."/panel.js", base64_decode("")) !== false;
@unlink(__FILE__);
header("Content-Type: text/html; charset=utf-8");
echo $ok
  ? "<p style=\"font:1rem monospace;background:#0f0d0a;color:#7fcf9a;padding:20px\">OK admin/panel.js deploye. Supprimez le cache : Ctrl+Shift+R</p>"
  : "<p style=\"font:1rem monospace;background:#0f0d0a;color:#f0b0b0;padding:20px\">ERREUR: ".htmlspecialchars(print_r(error_get_last(),true))."</p>";
